import { AsyncPipe } from '@angular/common';
import { Component, inject } from '@angular/core';
import { IonImg } from '@ionic/angular/standalone';
import { Observable, fromEvent, map, startWith } from 'rxjs';
import { WindowService } from '../window/window.service';

@Component({
    selector: 'app-logo',
    templateUrl: './logo.component.html',
    styleUrls: ['./logo.component.scss'],
    imports: [IonImg, AsyncPipe]
})
export class LogoComponent {
  private windowService = inject(WindowService);

  imgSrc$: Observable<string>;

  constructor() {
    const win = this.windowService.getWindow();
    const result = win.matchMedia('(prefers-color-scheme: dark)');
    const lightSrc = './assets/logo-light-mode.png';
    const darkSrc = './assets/logo-dark-mode.png';
    const darkOrLightSrc = (event: MediaQueryListEvent | MediaQueryList) =>
      event.matches ? darkSrc : lightSrc;
    this.imgSrc$ = fromEvent(result, 'change').pipe(
      map((event: unknown) => event as MediaQueryListEvent),
      map(darkOrLightSrc),
      startWith(darkOrLightSrc(result))
    );
  }
}
